const profile = $json.candidate_profile;
const job = $('Fetch Unscored Jobs').item.json;
const jobData = { id: job.id, title: job.title, company: job.company, city: job.city, work_model: job.work_model, description: job.description || '' };
const geminiInput = {
  instruction: 'Evaluate this job for the candidate. Return exactly one JSON object only: no markdown, code fence, commentary, or extra keys. Be conservative and do not inflate the score.',
  scoring_rules: ['Target-role proximity and genuine engineering/data/AI/backend/software relevance.', 'Technical skill overlap and missing required skills.', 'Requested experience and junior or entry-level suitability.', 'Location preference and work model.', 'Senior, lead, principal, architect, management, sales, support, and marketing roles must not receive a high score when unsuitable.'],
  recommendation_thresholds: { strong_apply: '85-100', apply: '70-84', maybe: '55-69', skip: '0-54' },
  output_schema: { match_score: 'integer 0-100', recommendation: 'strong_apply | apply | maybe | skip', summary: 'non-empty concise Turkish string', matched_skills: 'string[]', missing_skills: 'string[]' },
  candidate_profile: profile,
  job: jobData
};
return { json: { job_id: job.id, candidate_profile: profile, job: jobData, gemini_input: geminiInput } };

const base = $('Build Gemini Input').item.json;
const fallback = reason => ({ json: { ...base, gemini_valid: false, fallback_reason: reason, scoring_provider: 'fallback' } });
if ($json.error) return fallback('request_error');
const status = Number($json.statusCode || 200);
if (status === 429) return fallback('rate_limit_429');
if (status >= 500) return fallback(`server_${status}`);
if (status >= 400) return fallback(`http_${status}`);
try {
  const body = $json.body || $json;
  const text = body?.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('')?.trim();
  if (!text) return fallback('empty_response');
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const result = JSON.parse(cleaned);
  const valid = Number.isInteger(result.match_score) && result.match_score >= 0 && result.match_score <= 100 && typeof result.summary === 'string' && result.summary.trim().length > 0 && Array.isArray(result.matched_skills) && result.matched_skills.every(value => typeof value === 'string') && Array.isArray(result.missing_skills) && result.missing_skills.every(value => typeof value === 'string');
  if (!valid) return fallback('validation_failure');
  const score = result.match_score;
  const recommendation = score >= 85 ? 'strong_apply' : score >= 70 ? 'apply' : score >= 55 ? 'maybe' : 'skip';
  return { json: { ...base, ai_result: { match_score: score, recommendation, summary: result.summary.trim(), matched_skills: result.matched_skills, missing_skills: result.missing_skills }, gemini_valid: true, scoring_provider: 'gemini' } };
} catch { return fallback('malformed_response'); }

const base = $('Parse Structured JSON').item.json;
const fallback = reason => ({ json: { ...base, openai_valid: false, openai_fallback_reason: reason, scoring_provider: 'fallback' } });
if ($json.error) return fallback('openai_request_error');
const status = Number($json.statusCode || 200);
if (status === 401) return fallback('openai_auth_401');
if (status === 429) return fallback('openai_rate_limit_429');
if (status >= 500) return fallback(`openai_server_${status}`);
if (status >= 400) return fallback(`openai_http_${status}`);
try {
  const body = $json.body || $json;
  const text = body?.output?.flatMap(item => item.content || []).find(item => item.type === 'output_text')?.text?.trim();
  if (!text) return fallback('openai_empty_response');
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const result = JSON.parse(cleaned);
  const score = typeof result.match_score === 'string' && /^\d+$/.test(result.match_score.trim()) ? Number(result.match_score) : result.match_score;
  const valid = Number.isInteger(score) && score >= 0 && score <= 100 && typeof result.summary === 'string' && result.summary.trim().length > 0 && Array.isArray(result.matched_skills) && result.matched_skills.every(value => typeof value === 'string') && Array.isArray(result.missing_skills) && result.missing_skills.every(value => typeof value === 'string');
  if (!valid) return fallback('openai_validation_failure');
  const recommendation = score >= 85 ? 'strong_apply' : score >= 70 ? 'apply' : score >= 55 ? 'maybe' : 'skip';
  return { json: { ...base, ai_result: { match_score: score, recommendation, summary: result.summary.trim(), matched_skills: result.matched_skills, missing_skills: result.missing_skills }, openai_valid: true, scoring_provider: 'openai' } };
} catch { return fallback('openai_malformed_response'); }

const profile = $json.candidate_profile;
const job = $json.job;
const text = `${job.title} ${job.description}`.toLowerCase();
const normalize = value => value.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const skillAliases = {
  'Python':['python'], 'SQL':['sql'], 'PostgreSQL':['postgresql','postgres'], 'FastAPI':['fastapi'], 'Docker':['docker'],
  'REST API':['rest api','restful api'], 'Pandas':['pandas'], 'NumPy':['numpy'], 'Machine Learning':['machine learning','ml'],
  'Git':[' git ','git version'], 'GitHub':['github']
};
const matchedSkills = profile.skills.filter(skill => (skillAliases[skill] || [skill.toLowerCase()]).some(alias => ` ${text} `.includes(alias === ' git ' ? alias : alias)));
const requiredSkillAliases = { 'AWS':['aws'], 'Airflow':['airflow'], 'Spark':['spark'], 'PyTorch':['pytorch'], 'TensorFlow':['tensorflow'], 'Cloud':['cloud'], 'ETL':['etl'], 'Deep Learning':['deep learning'] };
const candidateKnown = new Set([...profile.skills, ...profile.learning_skills].map(normalize));
const missingSkills = Object.entries(requiredSkillAliases).filter(([skill, aliases]) => aliases.some(alias => text.includes(alias)) && !candidateKnown.has(normalize(skill))).map(([skill]) => skill);
const normalizedTitle = normalize(job.title);
const targetRole = profile.target_roles.some(role => normalizedTitle.includes(normalize(role)));
const preferredLocation = profile.preferred_locations.some(location => normalize(job.city || '').includes(normalize(location)));
const juniorSignal = /\b(junior|entry[ -]?level|graduate|new[ -]?grad|trainee|intern(?:ship)?)\b/i.test(job.title);
let matchScore = 20 + (targetRole ? 25 : 0) + Math.min(matchedSkills.length * 7, 35) + (preferredLocation ? 10 : 0) + (juniorSignal ? 10 : 0);
matchScore = Math.max(0, Math.min(100, Math.round(matchScore)));
const recommendation = matchScore >= 85 ? 'strong_apply' : matchScore >= 70 ? 'apply' : matchScore >= 55 ? 'maybe' : 'skip';
const summary = `${job.title} pozisyonu aday profiliyle ${matchedSkills.length} beceri üzerinden eşleşiyor; mock skor ${matchScore}/100.`;
return { json: { ...$json, ai_result: { match_score: matchScore, recommendation, summary, matched_skills: matchedSkills, missing_skills: missingSkills }, scoring_mode: 'mock_deterministic' } };
